const body = $input.first().json.body || {};
try {
  // Guarda de origen: solo aceptamos webhooks reales de WhatsApp
  if (body.object !== 'whatsapp_business_account') { return []; }
  const ch = (((body.entry || [])[0] || {}).changes || [])[0] || {};
  const value = ch.value || {};
  const msg = (value.messages || [])[0];
  if (!msg) { return []; }
  const contact = (value.contacts || [])[0] || {};
  const t = msg.type;
  let texto_directo = '', es_audio = false, audio_id = '';
  if (t === 'text') {
    texto_directo = (msg.text || {}).body || '';
  } else if (t === 'audio') {
    es_audio = true;
    audio_id = (msg.audio || {}).id || '';
  } else {
    texto_directo = '[El cliente envio un mensaje de tipo ' + t + '. Pidele que te escriba por texto o por voz.]';
  }
  return [{ json: {
    from: msg.from, nombre: (contact.profile || {}).name || '',
    tipo: t, message_id: msg.id,
    es_audio: es_audio, audio_id: audio_id, texto_directo: texto_directo
  } }];
} catch (e) { return []; }

const ex = $('Extraer mensaje').item.json;
const inc = $input.first().json || {};
let texto;
if (typeof inc.text === 'string' && inc.text.trim() !== '') {
  texto = inc.text.trim();
} else {
  texto = ex.texto_directo || '';
}
if (!texto) { texto = '(mensaje vacio)'; }
return [{ json: {
  from: ex.from, nombre: ex.nombre, tipo: ex.tipo,
  message_id: ex.message_id, es_audio: ex.es_audio, texto: texto
} }];

