let raw = String(($input.first().json.output) || '').trim();
raw = raw.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
let p = null;
try { p = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { p = JSON.parse(m[0]); } catch (e2) { p = null; } }
}
if (!p || typeof p !== 'object') { p = { respuesta: raw, accion: 'ninguna', datos: {} }; }
if (!p.respuesta) { p.respuesta = 'Disculpa, no te entendi bien. Me lo repites por favor?'; }
if (!p.accion) { p.accion = 'ninguna'; }
if (!p.datos || typeof p.datos !== 'object') { p.datos = {}; }
return [{ json: p }];
